import{_ as a}from"./chunks/icon.DxQwhVtI.js";import{_ as t,a as s,b as o}from"./chunks/cards-177.DbNRxSpU.js";import{_ as n,o as i,c as r,a3 as l}from"./chunks/framework.BlfGB29P.js";const y=JSON.parse('{"title":"Automation Status Card","description":"Automatic automation list, checkbox selection, running status and trace diagnostics. Version 0.1.3, DE/EN/FR.","frontmatter":{"title":"Automation Status Card","description":"Automatic automation list, checkbox selection, running status and trace diagnostics. Version 0.1.3, DE/EN/FR."},"headers":[],"relativePath":"en/projects/automation-status-card/index.md","filePath":"en/projects/automation-status-card/index.md","lastUpdated":1794476856000}'),c={name:"en/projects/automation-status-card/index.md"};function d(u,e,p,h,m,g){return i(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="automation-status-card" tabindex="-1">Automation Status Card <a class="header-anchor" href="#automation-status-card" aria-label="Permalink to &quot;Automation Status Card&quot;">​</a></h1><p><strong>HA 2026.11.0, 2026-11-05, .177:</strong> Version 0.1.3 passes rendering, on/off with state confirmation, running status, trace requests, normal completion, checkboxes, select/deselect all and reload. Bubble/Mushroom single-automation examples render. Owned test objects were removed. Failures and runtime warnings were not deliberately triggered again on this HA version; earlier results remain recorded separately.</p><p><a href="/en/collection/ha-2026-11-compatibility">Scope, results and remaining findings</a>.</p><img src="'+a+`" width="80" height="80" alt="Automation Status Card"><p><strong>0.1.3 · DE / EN / FR · MIT</strong></p><p><a href="https://github.com/rockbaer2007/automation-status-card" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://github.com/rockbaer2007/automation-status-card/releases/tag/v0.1.3" target="_blank" rel="noreferrer">Download 0.1.3</a> · <a href="https://opensource.ugso-software.de/en/projects/automation-status-card/" target="_blank" rel="noreferrer">Documentation</a></p><p>Verified on .177 with HA 2026.10.4: the 0.1.0 base card and selection/diagnostics in corrected version 0.1.3. Actual HA traces, failure, normal completion, running warnings, disabled warnings, checkboxes and saved selection passed. <a href="https://github.com/rockbaer2007/automation-status-card/blob/main/docs/TESTING.md" target="_blank" rel="noreferrer">Report and screenshots</a>.</p><p>Automatically lists all <code>automation.*</code> entities available to the signed-in HA user, sorted alphabetically. Eight rows are visible by default; further entries scroll vertically. New/deleted automations update automatically. No additional card library is required.</p><h2 id="install-and-configure" tabindex="-1">Install and configure <a class="header-anchor" href="#install-and-configure" aria-label="Permalink to &quot;Install and configure&quot;">​</a></h2><h3 id="hacs-marketplace" tabindex="-1">HACS / Marketplace <a class="header-anchor" href="#hacs-marketplace" aria-label="Permalink to &quot;HACS / Marketplace&quot;">​</a></h3><p>HACS / Marketplace: add <code>https://github.com/rockbaer2007/automation-status-card</code> as a custom <strong>Dashboard</strong> (<code>plugin</code>) repository. Resource: <code>/hacsfiles/automation-status-card/automation-status-card.js</code>. HACS-compatible packaging does not mean inclusion in the default catalog; a separate Marketplace installation has not been tested. This is not a Supervisor app. Load either the HACS or manual copy, never both.</p><h3 id="manual-installation" tabindex="-1">Manual installation <a class="header-anchor" href="#manual-installation" aria-label="Permalink to &quot;Manual installation&quot;">​</a></h3><p>Back up HA. Copy the packaged <code>automation-status-card.js</code> to <code>/config/www/automation-status-card/automation-status-card.js</code>. Add <code>/local/automation-status-card/automation-status-card.js</code> in <strong>Settings → Dashboards → Resources</strong>, type <strong>JavaScript module</strong>, preserving existing resources. Reload the dashboard and select <strong>Automation Status Card</strong> in the picker.</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">custom:automation-status-card</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Automations</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">visible_rows</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">allow_toggle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">language</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">auto</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>The visual editor exposes title, visible rows (integer 1–50), <strong>Allow toggling</strong>, and language (<code>auto</code>, <code>de</code>, <code>en</code>, <code>fr</code>). An empty title hides the heading. Automatic language follows HA, falling back to English.</p><p><strong>Show automations</strong> initially checks every entry: <strong>checked = show</strong>, unchecked = hide only in this card. <strong>Select all</strong> shows every entry; <strong>Deselect all</strong> hides all currently listed entries. Newly discovered automations are selected by default. Selection is saved per card without changing automations or other cards. Temporarily unavailable, deselected entities remain listed so they can be selected again. Optional YAML: <code>hidden_entities: [automation.my_automation]</code> lists deselected IDs. Omitting it preserves the previous behavior.</p><p>On/Off means <strong>enabled/disabled</strong>, not currently running. Names open HA’s more-info dialog. With controls enabled, each switch enables/disables exactly that automation; the card never calls a trigger service. Disabling uses <code>stop_actions: false</code> to avoid explicitly stopping an existing run. HA permissions still apply; display-only mode is not access control.</p><p>Unavailable/unknown entities and disconnected clients cannot be switched. A pending switch is blocked until the state is confirmed. Errors or missing confirmation are reported without automatic retries or optimistic success.</p><h2 id="running-status-and-diagnostics" tabindex="-1">Running status and diagnostics <a class="header-anchor" href="#running-status-and-diagnostics" aria-label="Permalink to &quot;Running status and diagnostics&quot;">​</a></h2><p>HA reports some interruptions only as <code>aborted</code>, including a false condition or an explicit error stop. These are labelled neutrally <strong>Last run aborted – check the reason in HA traces</strong>, without claiming success or failure. Trace-based durations are always capped at time observed by this card, preventing HA/browser clock differences from causing premature warnings.</p><p><code>show_health: true</code> (default) adds running count and duration from HA’s <code>current</code> attribute, independently of On/Off. <code>runtime_warning_seconds: 300</code> warns after five minutes; <code>0</code> disables the warning, maximum 604800 seconds (7 days). All settings are available in the visual editor. Long runtime does not prove a crash: delays and waits may be intentional. Nothing is automatically stopped or restarted.</p><p>With a complete matching trace list, duration uses the oldest active run. Otherwise it starts conservatively when this card observes activity and is labelled accordingly. <code>last_triggered</code> alone is not used as runtime; a trigger newer than the last trace request also causes observation-time fallback. Navigation, reload or disconnect clears local observation. This is not a background watchdog.</p><p><code>check_traces: true</code> (default) reads automation <code>trace/list</code> summaries at most every 30 seconds for administrators, plus a manual refresh button. It never requests full traces, variables or configurations. The newest completed run is marked failed only if HA reports an error; a normal stop or false condition is not automatically a failure. A newer completed run without reported error replaces an older error indication. The timestamp is available in the tooltip; names still open HA details.</p><p>Missing admin rights, automation IDs or stored traces, unsupported API and connection errors are reported as unavailable diagnostics, not automation failures. Disconnection suppresses stale run status. Rights are never expanded. An action error ignored with <code>continue_on_error</code> may be absent from the summary. The built-in HA API may change in later versions. Sources: <a href="https://www.home-assistant.io/docs/automation/basics/" target="_blank" rel="noreferrer">attributes</a>, <a href="https://github.com/home-assistant/core/blob/2026.10.4/homeassistant/components/trace/websocket_api.py" target="_blank" rel="noreferrer">trace API</a>, <a href="https://github.com/home-assistant/core/blob/2026.10.4/homeassistant/components/trace/models.py" target="_blank" rel="noreferrer">summary schema</a>.</p><h2 id="bubble-card-and-mushroom-one-automation" tabindex="-1">Bubble Card and Mushroom: one automation <a class="header-anchor" href="#bubble-card-and-mushroom-one-automation" aria-label="Permalink to &quot;Bubble Card and Mushroom: one automation&quot;">​</a></h2><p><code>examples/bubble-single-readonly.yaml</code> and <code>bubble-single-control.yaml</code>, plus <code>mushroom-single-readonly.yaml</code> and <code>mushroom-single-control.yaml</code>, each target <strong>one</strong> automation. Replace <code>automation.replace_me</code> with its entity ID. Read-only examples disable card actions; control examples use the extension’s ordinary toggle action and its own standard action behavior. They are standalone YAML templates, not automatic lists or additional custom extension code. The main card’s <code>allow_toggle</code> setting does not control those separate cards.</p><p>Install the appropriate extension separately. Case-sensitive resource paths:</p><ul><li>Bubble Card: <code>/hacsfiles/Bubble-Card/bubble-card.js</code></li><li>Mushroom: <code>/hacsfiles/lovelace-mushroom/mushroom.js</code></li></ul><p>Existing cards are not changed and third-party code is not bundled. <a href="https://github.com/Clooos/Bubble-Card" target="_blank" rel="noreferrer">Bubble Card</a> · <a href="https://github.com/piitaya/lovelace-mushroom" target="_blank" rel="noreferrer">Mushroom</a>.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>Release includes the built JS asset and a complete ZIP with instructions/examples. For manual updates, retain the existing resource path, update its <code>?v=0.1.3</code> query and fully reload the browser. Node 22+: <code>npm ci</code>, <code>npm run check</code>, <code>npm run build</code>, <code>npm test</code>. <a href="https://github.com/rockbaer2007/automation-status-card/blob/main/docs/TESTING.md" target="_blank" rel="noreferrer">Verification</a>.</p><p>MIT license. No external runtime services, credentials or telemetry. HA stores the dashboard configuration; the card does not edit automation definitions.</p><p><img src="`+t+'" alt="HA test: run warning and failure"></p><p><img src="'+s+'" alt="HA editor: selection"></p><p><img src="'+o+'" alt="Single-automation examples, initial-version test"></p>',35)])])}const v=n(c,[["render",d]]);export{y as __pageData,v as default};
